// 整理素材 —— 只留最近几条，拼成一段交给模型的文字
// 模式：全部数据只跑一次
// 字段名以“抓订阅源”那个节点的输出面板为准，各站点的 RSS 写法有出入

const 最多几条 = 8;

const 条目 = $input.all().slice(0, 最多几条);

const 行 = 条目.map((一条, 序号) => {
  const j = 一条.json;
  const 标题 = String(j.title || '无标题').trim();
  const 链接 = String(j.link || '').trim();
  const 摘录 = String(j.contentSnippet || j.description || j.content || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 500);
  return `${序号 + 1}. ${标题}\n链接：${链接}\n原文摘录：${摘录}`;
});

return [{ json: { 条数: 条目.length, 用户内容: 行.join('\n\n') } }];

