// 拼日报 —— 把模型写的那段套上标题和日期，顺便算出文件名
// 模式：全部数据只跑一次

const 摘要 = String(
  ($json.choices && $json.choices[0] && $json.choices[0].message
    && $json.choices[0].message.content) || ''
).trim();

const 两位 = (n) => String(n).padStart(2, '0');
const d = new Date();
const 日期 = `${d.getFullYear()}-${两位(d.getMonth() + 1)}-${两位(d.getDate())}`;

const 条数 = $('整理素材').first().json.条数;

const 正文 = [
  `# 日报 ${日期}`,
  ``,
  `今天抓到 ${条数} 条。`,
  ``,
  摘要 || '（模型没有返回内容，去执行记录里点开“问模型”那个节点看）',
  ``,
  `———— 以上内容由本地模型摘出，原文以链接为准。`,
  ``,
].join('\n');

return [{
  json: {
    日期: 日期,
    文件名: `日报-${日期}.md`,
    路径: `/data/日报-${日期}.md`,
    正文: 正文,
  },
}];
